#ifndef AXIS_DMA_REGS_H
#define AXIS_DMA_REGS_H
#define AXIS_DMA_REGS_ID_OFFSET 0x00u
#define AXIS_DMA_REGS_VERSION_OFFSET 0x04u
#define AXIS_DMA_REGS_DATE_OFFSET 0x08u
#define AXIS_DMA_REGS_ID_VALUE 0x41444D41u   /* "ADMA" */
#define AXIS_DMA_REGS_CTRL_OFFSET 0x10u   /* RW */
#define AXIS_DMA_REGS_CTRL_RESET 0x00000000u
#define AXIS_DMA_REGS_CTRL_MM2S_START_SHIFT 0u
#define AXIS_DMA_REGS_CTRL_MM2S_START_MASK 0x00000001u
#define AXIS_DMA_REGS_CTRL_S2MM_START_SHIFT 1u
#define AXIS_DMA_REGS_CTRL_S2MM_START_MASK 0x00000002u
#define AXIS_DMA_REGS_CTRL_IRQ_EN_SHIFT 2u
#define AXIS_DMA_REGS_CTRL_IRQ_EN_MASK 0x00000004u
#define AXIS_DMA_REGS_MM2S_ADDR_OFFSET 0x14u   /* RW */
#define AXIS_DMA_REGS_MM2S_ADDR_RESET 0x00000000u
#define AXIS_DMA_REGS_MM2S_LEN_OFFSET 0x18u   /* RW */
#define AXIS_DMA_REGS_MM2S_LEN_RESET 0x00000000u
#define AXIS_DMA_REGS_S2MM_ADDR_OFFSET 0x1Cu   /* RW */
#define AXIS_DMA_REGS_S2MM_ADDR_RESET 0x00000000u
#define AXIS_DMA_REGS_S2MM_LEN_OFFSET 0x20u   /* RW */
#define AXIS_DMA_REGS_S2MM_LEN_RESET 0x00000000u
#define AXIS_DMA_REGS_STATUS_OFFSET 0x24u   /* CMD */
#define AXIS_DMA_REGS_STATUS_RESET 0x00000000u
#define AXIS_DMA_REGS_STATUS_MM2S_BUSY_SHIFT 0u
#define AXIS_DMA_REGS_STATUS_MM2S_BUSY_MASK 0x00000001u
#define AXIS_DMA_REGS_STATUS_S2MM_BUSY_SHIFT 1u
#define AXIS_DMA_REGS_STATUS_S2MM_BUSY_MASK 0x00000002u
#define AXIS_DMA_REGS_STATUS_MM2S_DONE_SHIFT 8u
#define AXIS_DMA_REGS_STATUS_MM2S_DONE_MASK 0x00000100u
#define AXIS_DMA_REGS_STATUS_S2MM_DONE_SHIFT 9u
#define AXIS_DMA_REGS_STATUS_S2MM_DONE_MASK 0x00000200u
#define AXIS_DMA_REGS_STATUS_MM2S_ERR_SHIFT 10u
#define AXIS_DMA_REGS_STATUS_MM2S_ERR_MASK 0x00000400u
#define AXIS_DMA_REGS_STATUS_S2MM_ERR_SHIFT 11u
#define AXIS_DMA_REGS_STATUS_S2MM_ERR_MASK 0x00000800u
#endif /* AXIS_DMA_REGS_H */
